"""docs/literature.md is generated by scripts/build_literature.py; code cites sources as [key locator] comments."""
import ast
import subprocess
import sys
from pathlib import Path

REPO = Path(__file__).resolve().parents[1]


def test_register_is_current_and_code_cites_only_registered_keys():
    r = subprocess.run([sys.executable, str(REPO / "scripts" / "build_literature.py"), "--check"],
                       capture_output=True, text=True, encoding="utf-8")
    assert r.returncode == 0, r.stderr


def test_every_scanned_directory_exists():
    """A moved folder must not drop out of the citation check silently."""
    src = (REPO / "scripts" / "build_literature.py").read_text(encoding="utf-8")
    line = next(l for l in src.splitlines() if l.startswith("CITE_DIRS = "))
    dirs = ast.literal_eval(line.split("=", 1)[1].strip())
    assert [d for d in dirs if not (REPO / d).is_dir()] == []
